const defaultBranding: Branding = { platformName: "Arbitrade", tagline: "market intelligence", browserTitle: "Arbitrade Crypto Opportunity Platform", logoUrl: "/arbitrade-mark.svg", faviconUrl: "/arbitrade-mark.svg", shareImageUrl: "/arbitrade-mark.svg", accentColor: "#7CE7C2" };
function playNotificationChime(){ try { const C=window.AudioContext||((window as unknown as {webkitAudioContext?:typeof AudioContext}).webkitAudioContext); if(!C)return; const c=new C(); const o=c.createOscillator(); const g=c.createGain(); o.type="sine"; o.frequency.value=740; g.gain.setValueAtTime(.0001,c.currentTime); g.gain.exponentialRampToValueAtTime(.08,c.currentTime+.01); g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.18); o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.2); } catch {} }
function getBranding(): Branding { try { const saved=localStorage.getItem("arbitrade_branding"); return saved ? {...defaultBranding,...JSON.parse(saved)} : defaultBranding; } catch { return defaultBranding; } }
function applyBranding(branding: Branding) { if (typeof document === "undefined") return; document.title=branding.browserTitle || branding.platformName; let link=document.querySelector<HTMLLinkElement>('link[rel="icon"]'); if (!link) { link=document.createElement("link"); link.rel="icon"; document.head.appendChild(link); } link.href=branding.faviconUrl || branding.logoUrl; document.documentElement.style.setProperty("--brand-accent",branding.accentColor || defaultBranding.accentColor); }

